/**
 * Source-line helpers. A line ends at `\n` or `\r\n`; the two characters of a
 * `\r\n` always stay together, so no helper returns an offset between them.
 */

/** A line break the editor inserts into source text. */
export type LineBreak = '\n' | '\r\n';

/** The first line break in `text`, or `'\n'` when it has none. */
export function detectLineBreak(text: string): LineBreak {
	const newline = text.indexOf('\n');
	return newline > 0 && text[newline - 1] === '\r' ? '\r\n' : '\n';
}

/** Replaces every `\r\n`, `\r` and `\n` in `text` with `lineBreak`. */
export function normalizeLineBreaks(text: string, lineBreak: LineBreak): string {
	return text.replace(/\r\n|\r|\n/g, lineBreak);
}

/** Start of the line containing `offset`. */
export function lineStart(text: string, offset: number): number {
	return offset <= 0 ? 0 : text.lastIndexOf('\n', offset - 1) + 1;
}

/** End of the line containing `offset`, excluding its line break. */
export function lineEnd(text: string, offset: number): number {
	const newline = text.indexOf('\n', offset);
	if (newline === -1) { return text.length; }
	return newline > 0 && text[newline - 1] === '\r' ? newline - 1 : newline;
}

/** Start of the line after the one containing `offset`, or `undefined` on the last line. */
export function nextLineStart(text: string, offset: number): number | undefined {
	const newline = text.indexOf('\n', offset);
	return newline === -1 ? undefined : newline + 1;
}

/**
 * Start of the last line break that ends at or before `offset`, or
 * `undefined` if there is none.
 */
export function previousLineBreakStart(text: string, offset: number): number | undefined {
	if (offset <= 0) { return undefined; }
	const newline = text.lastIndexOf('\n', offset - 1);
	if (newline === -1) { return undefined; }
	return newline > 0 && text[newline - 1] === '\r' ? newline - 1 : newline;
}

/** Length of the line break starting at `offset`: 2 for `\r\n`, 1 for `\n`, otherwise 0. */
export function lineBreakLengthAt(text: string, offset: number): 0 | 1 | 2 {
	if (text[offset] === '\n') { return 1; }
	return text[offset] === '\r' && text[offset + 1] === '\n' ? 2 : 0;
}

/** Whether `offset` lies between the `\r` and `\n` of a `\r\n`. */
export function isInsideLineBreak(text: string, offset: number): boolean {
	return text[offset - 1] === '\r' && text[offset] === '\n';
}
